CREATE TRIGGER orders_snapshot_immutable BEFORE UPDATE OF snapshot_json ON public.orders FOR EACH ROW WHEN ((old.snapshot_json IS NOT NULL)) EXECUTE FUNCTION public.pp_abort('order snapshot is immutable');

--
-- Name: orders orders_terms_immutable; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER orders_terms_immutable BEFORE UPDATE OF subtotal_cents, shipping_cents, tax_cents, total_cents, buyer_id, seller_id, payment_mode ON public.orders FOR EACH ROW EXECUTE FUNCTION public.pp_abort('order terms are immutable');

--
-- Name: processor_reports processor_reports_frozen; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER processor_reports_frozen BEFORE UPDATE ON public.processor_reports FOR EACH ROW WHEN (((old.status = 'submitted'::text) OR (new.case_id <> old.case_id) OR (new.packet <> old.packet) OR (new.provider <> old.provider) OR (new.prepared_at <> old.prepared_at))) EXECUTE FUNCTION public.pp_abort('a submitted processor report cannot be changed');

--
-- Name: processor_reports processor_reports_no_delete; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER processor_reports_no_delete BEFORE DELETE ON public.processor_reports FOR EACH ROW EXECUTE FUNCTION public.pp_abort('processor reports are append-only');

--
-- Name: review_events review_events_no_delete; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER review_events_no_delete BEFORE DELETE ON public.review_events FOR EACH ROW EXECUTE FUNCTION public.pp_abort('review history is append-only');

--
-- Name: review_events review_events_no_update; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER review_events_no_update BEFORE UPDATE ON public.review_events FOR EACH ROW EXECUTE FUNCTION public.pp_abort('review history is append-only');

--
-- Name: review_photos review_photos_max3; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER review_photos_max3 BEFORE INSERT OR UPDATE OF review_id, status ON public.review_photos FOR EACH ROW EXECUTE FUNCTION public.pp_review_photo_limit();

--
